const n = 75;

// De número a texto en binario
console.log(n.toString(2));                    // 1001011
console.log(n.toString(2).padStart(8, "0"));  // 01001011

// De texto binario a número
console.log(parseInt("11010110", 2));          // 214

// Escribir un binario directamente en el código
console.log(0b11111111);                       // 255

// Cuántas combinaciones hay con n bits
console.log(2 ** 8, 2 ** 16, 2 ** 32);
